function errorPage(chain, id, origin) {
  const clean = origin + '/';
  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>PrimePulse OPS — Scan Input Error</title><link rel="icon" href="${LOGO}" type="image/png"><meta property="og:title" content="PrimePulse OPS — Scan Input Error"><meta property="og:description" content="Use a DexScreener pair URL, pair address or token contract."><style>body{background:#020408;color:#e0f7ff;font-family:Arial;display:grid;place-items:center;min-height:100vh;padding:20px}.box{max-width:720px;border:1px solid rgba(255,51,95,.4);background:rgba(255,51,95,.06);padding:28px;line-height:1.7}code{color:#00f5ff}</style></head><body><div class="box"><h2>SCAN COULD NOT RESOLVE</h2><p>Input received:</p><code>${esc(id)}</code><p>Use a DexScreener pair URL, pair address or token contract. The clean format is:</p><code>${esc(origin)}/scan/solana/PAIR_ADDRESS</code><p><a style="color:#00f5ff" href="${clean}">Open generator</a></p></div></body></html>`;
}
export default async function handler(req, res) {
  try {
    const url = new URL(req.url, `https://${req.headers.host}`);
    const parts = url.pathname.split('/').filter(Boolean);
    let chain = parts[1] || url.searchParams.get('chain') || 'solana';
    let id = parts.slice(2).join('/') || url.searchParams.get('id') || url.searchParams.get('url') || '';
    const origin = `https://${req.headers.host}`;
    const normalized = normalizeInput(chain, id);
    chain = normalized.chain;
    id = normalized.id;

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 's-maxage=15, stale-while-revalidate=30');

    if (!id || id.length < 8) {
      res.status(400).send(errorPage(chain, id, origin));
      return;
    }

    const pair = await getPair(chain, id);
    if (!pair) {
      res.status(404).send(errorPage(chain, id, origin));
      return;
    }
    res.status(200).send(renderPage({chain, id, pair, origin}));
  } catch (e) {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.status(500).send(errorPage('unknown', String(e.message || e), `https://${req.headers.host}`));
  }
}
